 New-RepatoTask $store $task 'Maya QA request' 'Create Plan Views' 'qa/maya-qa-workflow' 'maya'|Out-Null
 Invoke-RepatoStoreMutation $store {param($d,$p)$t=Find-RepatoTask $d $task;$t|Add-Member NoteProperty mayaTaraAttempt ([pscustomobject]@{TaskId=$task;WorkflowId=$workflow;QaWorkflowId=$qa;RunId=$run;AttemptId=$attempt;RequestExpiresUtc=([DateTimeOffset]::UtcNow.AddMinutes(30).ToString('O'))}) -Force;$t}|Out-Null
 $request={param($s,$u,$b,$p)$events.Add('request');[pscustomobject]@{Stage='handoff-ready';TaskId=$task;WorkflowId=$workflow;QaWorkflowId=$qa;RunId=$run;Handoff=[pscustomobject]@{HandoffId='synthetic-handoff';NativeTestId=$qa;ArtifactPath='artifact';ArtifactSha256=('a'*64);ManifestPath='manifest';ManifestSha256=('b'*64);RunnerManifestPath='manifest';RunnerManifestSha256=('b'*64);ValidatedRunnerManifestPath='manifest';ModelPath='model';ModelSha256=('c'*64);Isolation=[pscustomobject]@{PolicyPath='policy';PolicySha256=('d'*64);Allowed=$true}}}}
 $record={param($s,$id,$preflight)$events.Add('execution');if($preflight.AttemptId -cne $attempt){throw 'Persisted AttemptId was not bound.'};[pscustomobject]@{TaskId=$id;WorkflowId=$workflow;QaWorkflowId=$qa;AttemptId=$attempt;RunId=$run;ClaimId=$null}}
 $claimFn={param($s,$id,$owner,$execution)$events.Add('claim');$execution|Add-Member NoteProperty ClaimId 'synthetic-claim' -Force;$execution};$native={param($s,$id,$claim)$events.Add('native-core');[pscustomobject]@{Success=$true;Stage='completed'}}
 $out=Invoke-MayaQaCanonicalTransaction -StoreRoot $store -UserRequest 'synthetic' -RequestInvoker $request -ExecutionRecordInvoker $record -ClaimInvoker $claimFn -NativeCoreInvoker $native
 if(($events -join '|') -cne 'request|execution|claim|native-core' -or $out.Execution.AttemptId -cne $attempt){throw 'Valid persisted attempt binding failed.'}
 foreach($case in 'missing-attempt','blank-attempt','wrong-run','mismatched-handoff','missing-manifest','missing-qa','blank-qa','wrong-qa','wrong-workflow','wrong-attempt'){
