  switch($case){'missing-attempt'{$t.PSObject.Properties.Remove('mayaTaraAttempt')};'blank-attempt'{$bad.AttemptId='';$t.mayaTaraAttempt=$bad};'wrong-run'{$bad.RunId='wrong';$t.mayaTaraAttempt=$bad};'mismatched-handoff'{$handoffAttempt='wrong'};'missing-manifest'{$badRequest={param($s,$u,$b,$p)$x=& $request $s $u $b $p;$x.Handoff.PSObject.Properties.Remove('ValidatedRunnerManifestPath');$x};};'missing-qa'{$bad.PSObject.Properties.Remove('QaWorkflowId');$t.mayaTaraAttempt=$bad};'blank-qa'{$bad.QaWorkflowId='';$t.mayaTaraAttempt=$bad};'wrong-qa'{$bad.QaWorkflowId='wrong';$t.mayaTaraAttempt=$bad};'wrong-workflow'{$bad.WorkflowId='wrong';$t.mayaTaraAttempt=$bad};'wrong-attempt'{$bad.AttemptId='wrong';$t.mayaTaraAttempt=$bad}}
  Write-RepatoJsonAtomic (Join-Path $store 'tasks.json') $d;$rejected=$false;try{$ri=$badRequest;if($handoffAttempt){$ri={param($s,$u,$b,$p)$x=& $request $s $u $b $p;$x.Handoff|Add-Member NoteProperty AttemptId 'wrong' -Force;$x};};Invoke-MayaQaCanonicalTransaction -StoreRoot $store -UserRequest 'synthetic' -RequestInvoker $ri -ExecutionRecordInvoker $record -ClaimInvoker $claimFn -NativeCoreInvoker $native|Out-Null}catch{$rejected=$true};if(!$rejected){throw "Negative case accepted: $case"};$d=Read-RepatoTaskStore $store;$t=Find-RepatoTask $d $task;if($case -eq 'missing-attempt'){$t|Add-Member NoteProperty mayaTaraAttempt $original -Force}else{$t.mayaTaraAttempt=$original};Write-RepatoJsonAtomic (Join-Path $store 'tasks.json') $d
 }
 'Canonical transaction identity binding passed: valid persisted attempt + 10 fail-closed cases'
